//! PTY consumer interface.
//!
//! See `docs/architecture.md §3.3`.

/// What a session feeds PTY output into.
///
/// Defined in `termin-core` so `termin-pty` and `termin-vt` never depend on each other.
/// `termin_vt::Terminal` implements it; tests use a recording stub.
/// See `docs/architecture.md §3.3`.
pub trait PtyConsumer: Send + 'static {
    /// Effect type generated by parsing (e.g. `termin_vt::Effect`).
    type Effect: Send;

    /// Parse bytes received from PTY. Responses written to `write_back`, effects to `effects`.
    fn consume(&mut self, bytes: &[u8], write_back: &mut Vec<u8>, effects: &mut Vec<Self::Effect>);

    /// Resize terminal grid and pixel dimensions.
    fn resize(&mut self, cols: u16, rows: u16, px: (u16, u16));

    /// Generation counter incremented on visible changes.
    fn generation(&self) -> u64;
}

#[cfg(test)]
mod tests {
    use super::*;

    struct DummyConsumer {
        gen: u64,
        cols: u16,
        rows: u16,
    }

    impl PtyConsumer for DummyConsumer {
        type Effect = ();

        fn consume(
            &mut self,
            bytes: &[u8],
            write_back: &mut Vec<u8>,
            _effects: &mut Vec<Self::Effect>,
        ) {
            self.gen += 1;
            write_back.extend_from_slice(bytes);
        }

        fn resize(&mut self, cols: u16, rows: u16, _px: (u16, u16)) {
            self.cols = cols;
            self.rows = rows;
            self.gen += 1;
        }

        fn generation(&self) -> u64 {
            self.gen
        }
    }

    #[test]
    fn test_dummy_consumer() {
        let mut consumer = DummyConsumer {
            gen: 0,
            cols: 80,
            rows: 24,
        };
        let mut wb = Vec::new();
        let mut eff = Vec::new();
        consumer.consume(b"hello", &mut wb, &mut eff);
        assert_eq!(wb, b"hello");
        assert_eq!(consumer.generation(), 1);
    }
}
